INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'What is a stack, and what are its main operations?'), 1, 'Explains that a stack removes the most recently added item first.', ARRAY['lifo']::TEXT[]);
INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'What is a stack, and what are its main operations?'), 2, 'Explains that push adds to the top, pop removes the top, and peek reads the top without removing it.', ARRAY['push', 'pop', 'peek', 'top']::TEXT[]);
INSERT INTO question_library (category, difficulty, question_type, prompt, expected_keywords) VALUES ('Data Structures', 'Medium', 'Technical', 'How does a hash table work, and how are collisions handled?', ARRAY['hash function', 'bucket', 'key', 'collision', 'chaining', 'open addressing', 'o(1)']::TEXT[]) ON CONFLICT (prompt) DO UPDATE SET category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, expected_keywords = EXCLUDED.expected_keywords;
