INSERT INTO question_library (category, difficulty, question_type, prompt, expected_keywords) VALUES ('Algorithms', 'Medium', 'Technical', 'Compare merge sort and quick sort.', ARRAY['divide and conquer', 'pivot', 'merge', 'o(n log n)', 'o(n^2)', 'stable', 'in-place']::TEXT[]) ON CONFLICT (prompt) DO UPDATE SET category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, expected_keywords = EXCLUDED.expected_keywords;
INSERT INTO question_skills (question_id, skill_id) SELECT (SELECT id FROM question_library WHERE prompt = 'Compare merge sort and quick sort.'), s.id FROM skills AS s WHERE s.name = 'algorithms';
INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'Compare merge sort and quick sort.'), 1, 'Explains that both are divide and conquer algorithms: merge sort splits and merges halves, while quick sort partitions around a pivot.', ARRAY['divide and conquer', 'merge', 'pivot']::TEXT[]);
INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'Compare merge sort and quick sort.'), 2, 'States that merge sort is always O(n log n) while quick sort averages O(n log n) but can degrade to O(n^2).', ARRAY['o(n log n)', 'o(n^2)']::TEXT[]);
INSERT INTO rubric_criteria (question_id, position, text, keywords) VALUES ((SELECT id FROM question_library WHERE prompt = 'Compare merge sort and quick sort.'), 3, 'Explains that merge sort is stable but needs extra memory, while quick sort sorts in-place.', ARRAY['stable', 'in-place']::TEXT[]);
INSERT INTO question_library (category, difficulty, question_type, prompt, expected_keywords) VALUES ('Algorithms', 'Medium', 'Technical', 'What is the difference between breadth-first search and depth-first search?', ARRAY['queue', 'stack', 'level', 'recursion', 'shortest path', 'graph']::TEXT[]) ON CONFLICT (prompt) DO UPDATE SET category = EXCLUDED.category, difficulty = EXCLUDED.difficulty, question_type = EXCLUDED.question_type, expected_keywords = EXCLUDED.expected_keywords;
