DELETE FROM rubric_criteria WHERE question_id = (SELECT id FROM question_library WHERE prompt = 'Describe a time you had to organize messy information.');

COMMIT;

-- Validation
SELECT question_type, difficulty, COUNT(*) FROM question_library GROUP BY question_type, difficulty ORDER BY question_type, difficulty;
SELECT r.name, SUM(rs.weight) AS weight_total FROM roles AS r JOIN role_skills AS rs ON rs.role_id = r.id GROUP BY r.name ORDER BY r.name;
SELECT COUNT(*) AS questions_without_rubric FROM question_library AS ql WHERE NOT EXISTS (SELECT 1 FROM rubric_criteria AS rc WHERE rc.question_id = ql.id);
